            comment.reply = [];
          }

          // 添加到回复列表开头
          comment.reply.unshift(newReply);

          // 清空输入框
          comment.replyInput = '';
          comment.showReplyInput = false;
          comment.showEmojiPicker = false; // 关闭表情选择器

          // 更新评论的回复计数
          comment.reply_count = (comment.reply_count || 0) + 1;

          // 更新动态的总评论数
          moment.stats.comments += 1;
          ElMessage.success('回复成功');
        }
